@page "/dispatcher"
@rendermode InteractiveAuto
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Recipient</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td>@s.TrackingNumber</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>
                            <select class="form-select form-select-sm" @bind="s.Status">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                        <td>@s.ShippedDate.ToString("yyyy-MM-dd")</td>
                        <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>@s.RecipientName</td>
                        <td>
                            <button class="btn btn-primary btn-sm" @onclick="() => UpdateStatus(s)">
                                Update
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert @messageClass mt-2" role="alert">@message</div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string? message;
    private string messageClass = "alert-success";

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
        ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch
        {
            shipments = [];
            message = "Failed to load shipments.";
            messageClass = "alert-danger";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment)
    {
        try
        {
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}/status",
                new { Status = shipment.Status.ToString() });
            if (response.IsSuccessStatusCode)
            {
                message = $"Shipment {shipment.TrackingNumber} updated to {shipment.Status}.";
                messageClass = "alert-success";
            }
            else
            {
                message = $"Failed to update shipment {shipment.TrackingNumber}.";
                messageClass = "alert-danger";
            }
        }
        catch
        {
            message = "Error updating shipment status.";
            messageClass = "alert-danger";
        }
    }
}

@page "/track"
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-2026-00001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Shipment not found.</strong> Please check your tracking number and try again.
    </div>
}

@if (shipment != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <!-- Progress Indicator -->
            <div class="mb-4">
                <div class="d-flex justify-content-between mb-2">
                    @foreach (var step in progressSteps)
                    {
                        var isActive = GetStepIndex(shipment.Status) >= GetStepIndex(step);
                        var isCurrent = shipment.Status == step;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success" : "bg-secondary")"
                                 style="width: 36px; height: 36px;">
                                <span class="text-white fw-bold" style="font-size: 0.8rem;">
                                    @if (isActive) { <span>✓</span> } else { <span>○</span> }
                                </span>
                            </div>
                            <div class="small mt-1 @(isCurrent ? "fw-bold" : "")">@FormatStatus(step)</div>
                        </div>
                    }
                </div>
                <div class="progress" style="height: 6px;">
                    <div class="progress-bar bg-success" style="width: @(ProgressPercent)%"></div>
                </div>
            </div>

            @if (shipment.Status == ShipmentStatus.Exception)
            {
                <div class="alert alert-danger mb-3">
                    <strong>Exception:</strong> There is an issue with this shipment. Please contact support.
                </div>
            }

            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @StatusBadgeClass">@FormatStatus(shipment.Status)</span></dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>@(shipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "—")</dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd>@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isLoading;

    private readonly ShipmentStatus[] progressSteps =
    [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else
            {
                notFound = true;
            }
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private int GetStepIndex(ShipmentStatus status) =>
        Array.IndexOf(progressSteps, status) is var i && i >= 0 ? i : -1;

    private int ProgressPercent
    {
        get
        {
            if (shipment == null) return 0;
            var idx = GetStepIndex(shipment.Status);
            if (idx < 0) return 0;
            return idx * 100 / (progressSteps.Length - 1);
        }
    }

    private string StatusBadgeClass => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };
}

