// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Seed data
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();
    await SeedData.InitializeAsync(scope.ServiceProvider);
}

// API Endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.ToListAsync();
    return shipments.Select(s => new ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = Enum.Parse<ShipmentStatus>(s.Status),
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Notes = s.Notes
    });
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments
        .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    if (shipment is null) return Results.NotFound();

    return Results.Ok(new ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = Enum.Parse<ShipmentStatus>(shipment.Status),
        ShippedDate = shipment.ShippedDate,
        EstimatedDelivery = shipment.EstimatedDelivery,
        ActualDelivery = shipment.ActualDelivery,
        RecipientName = shipment.RecipientName,
        Notes = shipment.Notes
    });
}).AllowAnonymous();

app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();

    if (!Enum.TryParse<ShipmentStatus>(request.Status, out _))
        return Results.BadRequest("Invalid status value.");

    shipment.Status = request.Status;

    if (request.Status == nameof(ShipmentStatus.Delivered))
        shipment.ActualDelivery = DateTime.UtcNow;

    await db.SaveChangesAsync();
    return Results.Ok();
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

await app.RunAsync();

