6. <PageTitle>Dispatcher Dashboard</PageTitle>
7. 
8. <h2>Dispatcher Dashboard</h2>
9. 
10. <div class="mb-3">
11.     <input type="text" class="form-control" placeholder="Filter by tracking number or destination..."
12.            @bind="filterText" @bind:event="oninput" />
13. </div>
14. 
15. @if (shipments == null)
16. {
17.     <p><em>Loading shipments...</em></p>
18. }
19. else if (!FilteredShipments.Any())
20. {
21.     <p>No shipments found.</p>
22. }
23. else
24. {
25.     <div class="table-responsive">
26.         <table class="table table-striped table-hover">
27.             <thead class="table-dark">
28.                 <tr>
