36.                     <th>Action</th>
37.                 </tr>
38.             </thead>
39.             <tbody>
40.                 @foreach (var s in FilteredShipments)
41.                 {
42.                     <tr>
43.                         <td>@s.TrackingNumber</td>
44.                         <td>@s.Origin</td>
45.                         <td>@s.Destination</td>
46.                         <td>
