51.                                 }
52.                             </select>
53.                         </td>
54.                         <td>@s.ShippedDate.ToString("yyyy-MM-dd")</td>
55.                         <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
56.                         <td>@s.RecipientName</td>
57.                         <td>
58.                             <button class="btn btn-primary btn-sm" @onclick="() => UpdateStatus(s)">
59.                                 Update
60.                             </button>
61.                         </td>
62.                     </tr>
63.                 }
64.             </tbody>
65.         </table>
66.     </div>
67. }
68. 
