100. @code {
101.     private string trackingNumber = string.Empty;
102.     private ShipmentDto? shipment;
103.     private bool notFound;
104.     private bool isLoading;
105. 
106.     private readonly ShipmentStatus[] progressSteps =
107.     [
108.         ShipmentStatus.Pending,
109.         ShipmentStatus.PickedUp,
110.         ShipmentStatus.InTransit,
111.         ShipmentStatus.OutForDelivery,
112.         ShipmentStatus.Delivered
113.     ];
114. 
115.     private async Task TrackShipment()
116.     {
117.         if (string.IsNullOrWhiteSpace(trackingNumber)) return;
118. 
119.         isLoading = true;
120.         notFound = false;
121.         shipment = null;
122. 
123.         try
124.         {
125.             var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
126.             if (response.IsSuccessStatusCode)
127.             {
128.                 shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
129.             }
130.             else
131.             {
132.                 notFound = true;
133.             }
134.         }
135.         catch
136.         {
137.             notFound = true;
138.         }
139.         finally
140.         {
141.             isLoading = false;
142.         }
143.     }
144. 
145.     private async Task HandleKeyDown(KeyboardEventArgs e)
146.     {
147.         if (e.Key == "Enter")
148.         {
149.             await TrackShipment();
150.         }
151.     }
152. 
153.     private int GetStepIndex(ShipmentStatus status) =>
154.         Array.IndexOf(progressSteps, status) is var i && i >= 0 ? i : -1;
155. 
156.     private int ProgressPercent
157.     {
158.         get
159.         {
160.             if (shipment == null) return 0;
161.             var idx = GetStepIndex(shipment.Status);
162.             if (idx < 0) return 0;
163.             return idx * 100 / (progressSteps.Length - 1);
164.         }
165.     }
166. 
167.     private string StatusBadgeClass => shipment?.Status switch
168.     {
169.         ShipmentStatus.Delivered => "bg-success",
170.         ShipmentStatus.Exception => "bg-danger",
171.         ShipmentStatus.OutForDelivery => "bg-info",
172.         ShipmentStatus.InTransit => "bg-primary",
173.         ShipmentStatus.PickedUp => "bg-warning text-dark",
174.         _ => "bg-secondary"
175.     };
176. 
177.     private static string FormatStatus(ShipmentStatus status) => status switch
178.     {
179.         ShipmentStatus.PickedUp => "Picked Up",
180.         ShipmentStatus.InTransit => "In Transit",
181.         ShipmentStatus.OutForDelivery => "Out for Delivery",
182.         _ => status.ToString()
183.     };
184. }
185.

